import React, { useState, useEffect } from 'react';
import { reportService } from '../../services/reportService';
import '../../styles/table.scss';

const ReportsAttendance = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [yearMonth, setYearMonth] = useState(new Date().toISOString().slice(0, 7)); // YYYY-MM

  useEffect(() => {
    fetchReport();
  }, [yearMonth]);

  const fetchReport = async () => {
    try {
      setLoading(true);
      const result = await reportService.getAttendanceReport(yearMonth);
      if (result.success) {
        setData(result.data);
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Lỗi khi tải báo cáo chấm công');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="reports-page animate-fade-in" style={{ padding: '2rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '1.875rem', fontWeight: 'bold', color: '#1f2937' }}>Báo Cáo Chấm Công Tổng Hợp</h1>
        <div>
          <label style={{ marginRight: '1rem', fontWeight: '500' }}>Chọn tháng: </label>
          <input 
            type="month" 
            value={yearMonth}
            onChange={(e) => setYearMonth(e.target.value)}
            style={{ padding: '0.5rem', borderRadius: '8px', border: '1px solid #e5e7eb' }}
          />
        </div>
      </div>

      {error && <div style={{ padding: '1rem', backgroundColor: '#fee2e2', color: '#ef4444', borderRadius: '8px', marginBottom: '1rem' }}>{error}</div>}

      <div className="modern-table-container">
        {loading ? (
          <div style={{ padding: '2rem', textAlign: 'center' }}>Đang tạo báo cáo...</div>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Mã NV</th>
                <th>Họ Tên</th>
                <th>Phòng Ban</th>
                <th>Ngày công</th>
                <th>Nghỉ phép</th>
                <th>Không phép</th>
                <th>Tổng giờ làm</th>
              </tr>
            </thead>
            <tbody>
              {data.map((row) => (
                <tr key={row.EmployeeID}>
                  <td>EMP-{String(row.EmployeeID).padStart(5, '0')}</td>
                  <td style={{ fontWeight: '500' }}>{row.FullName}</td>
                  <td>{row.DepartmentName}</td>
                  <td><span className="status-badge present">{row.WorkDays}</span></td>
                  <td><span className="status-badge leave">{row.LeaveDays}</span></td>
                  <td><span className={row.AbsentDays > 0 ? "status-badge absent" : ""}>{row.AbsentDays}</span></td>
                  <td style={{ fontWeight: 'bold' }}>{row.WorkDays * 8} giờ</td>
                </tr>
              ))}
              {data.length === 0 && (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '2rem' }}>Không có dữ liệu báo cáo</td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default ReportsAttendance;
